struct i2c_rtio_iodev_data {
	struct k_work work;
	struct rtio_sqe *sqe;
	const struct device *dev;
};

static int i2c_rtio_init(const struct device *dev)
{
	struct i2c_rtio_iodev_data *data = dev->data;

	k_work_init(&data->work, i2c_iodev_submit_work_handler);

	return 0;
}

static int i2c_iodev_submit(const struct device *dev, struct rtio_sqe *sqe)
{
	struct i2c_rtio_iodev_data *data = dev->data;
	struct i2c_rtio_iodev_req *req = (struct i2c_rtio_iodev_req *)sqe->iodev_data;
	struct i2c_msg *msgs = req->msgs;
	int num_msgs = req->num_msgs;
	int ret;

	LOG_DBG("Executing fallback for dev: %p, sqe: %p", dev, sqe);

	/* If the request has read messages, we need to allocate buffers from the copy pool. */
	if (req->copy_pool != NULL) {
		for (int i = 0; i < num_msgs; i++) {
			if (msgs[i].flags & I2C_MSG_READ) {
				req->copy_pool_bufs[i] = rtio_spsc_acquire_empty(req->copy_pool,
										 msgs[i].len);
				if (req->copy_pool_bufs[i] == NULL) {
					LOG_ERR("Failed to acquire copy pool buffer for read message");
					/* Release any previously acquired buffers */
					for (int j = 0; j < i; j++) {
						if (msgs[j].flags & I2C_MSG_READ) {
							rtio_spsc_release(req->copy_pool,
									  req->copy_pool_bufs[j]);
						}
					}
					return -ENOMEM;
				}
				/* Update the message buffer to point to the copy pool buffer. */
				msgs[i].buf = req->copy_pool_bufs[i];
			}
		}
	}

	data->sqe = sqe;
	data->dev = dev;

	k_work_submit(&data->work);

	return 0;
}

static void i2c_iodev_submit_work_handler(struct k_work *work)
{
	struct i2c_rtio_work *i2c_work = CONTAINER_OF(work, struct i2c_rtio_work, work);
	const struct device *dev = i2c_work->dev;
	struct rtio_sqe *sqe = i2c_work->sqe;
	struct i2c_rtio_iodev_data *data = dev->data;
	struct i2c_rtio_iodev_api *api = (struct i2c_rtio_iodev_api *)dev->api;
	struct i2c_rtio_iodev_req *req = (struct i2c_rtio_iodev_req *)sqe->iodev_data;
	struct i2c_msg *msgs = req->msgs;
	int num_msgs = req->num_msgs;
	int ret;

	LOG_DBG("Sync RTIO work item for: %p", sqe);

	/* If the request has a copy pool, we need to copy the data to the user buffer. */
	if (req->copy_pool != NULL) {
		/* For read messages, the data is in the copy pool buffer. */
		for (int i = 0; i < num_msgs; i++) {
			if (msgs[i].flags & I2C_MSG_READ) {
				/* Copy from the copy pool buffer to the user buffer. */
				memcpy(msgs[i].buf, req->copy_pool_bufs[i], msgs[i].len);
			}
		}
	}

	ret = api->transfer(dev, msgs, num_msgs, req->addr);

	rtio_iodev_return_sync(sqe, ret);

	/* If the request has a copy pool, we need to release the buffers. */
	if (req->copy_pool != NULL) {
		for (int i = 0; i < num_msgs; i++) {
			rtio_spsc_release(req->copy_pool, req->copy_pool_bufs[i]);
		}
	}
}

